SELECT 'capture' AS section, capture_kind, status, finality, count() AS captures, sum(quote_rows) AS quote_rows, sum(request_rows) AS requests, sum(finalization_rows) AS finalizations, sum(claim_rows) AS claims, sum(funding_rows) AS funding_rows FROM crypto_market_info_lst.lst_capture FINAL GROUP BY capture_kind,status,finality ORDER BY capture_kind,status,finality FORMAT JSONEachRow;
SELECT 'quote' AS section, toString(purchase_budget_usdt_raw) AS usdt_raw, route_id, count() AS observations, countIf(buy_status='ok' AND conversion_status='ok' AND exit_status='ok' AND hedge_status='ok' AND timing_status='fresh') AS fresh_complete_quotes FROM crypto_market_info_lst.lst_quote_observation FINAL WHERE quote_role='entry' GROUP BY purchase_budget_usdt_raw,route_id ORDER BY purchase_budget_usdt_raw,route_id FORMAT JSONEachRow;
SELECT 'storage' AS section, table, sum(rows) AS physical_rows, sum(data_compressed_bytes) AS compressed_column_bytes, sum(bytes_on_disk) AS total_part_bytes FROM system.parts WHERE active AND database='crypto_market_info_lst' GROUP BY table ORDER BY table FORMAT JSONEachRow;
SELECT 'events' AS section, (SELECT count() FROM crypto_market_info_lst.lst_withdrawal_request FINAL) AS requests, (SELECT count() FROM crypto_market_info_lst.lst_withdrawal_finalization FINAL) AS finalizations, (SELECT count() FROM crypto_market_info_lst.lst_withdrawal_claim FINAL) AS claims, (SELECT uniqExact(instrument_id,funding_time) FROM crypto_market_info_lst.lst_funding_settlement FINAL) AS unique_funding_settlements FORMAT JSONEachRow;
